import subprocess, json, os, numpy as np, wave, base64
def call(name, args):
    r = subprocess.run(['ft2','call',name,json.dumps(args)],capture_output=True,text=True)
    out = r.stdout.strip()
    try:
        d = json.loads(out)
        return d['content'][0]['text'], d.get('isError', False)
    except Exception:
        return out + r.stderr, True
def batch(calls, path='/workspace/t/b.json'):
    json.dump([{'name':n,'arguments':a} for n,a in calls], open(path,'w'))
    r = subprocess.run(['ft2','batch',path],capture_output=True,text=True)
    return r.stdout[-3000:], r.returncode
def render(path='/workspace/t/r.wav', **kw):
    a = {'path':path,'rate':44100,'bits':16}
    a.update(kw)
    return call('module_render', a)
def readwav(path='/workspace/t/r.wav'):
    w=wave.open(path);n=w.getnframes()
    d=np.frombuffer(w.readframes(n),dtype='<i2').astype(float).reshape(-1,2)
    return d, w.getframerate()
def freq(x, sr=44100, thresh=100, nsamp=20000, off=200):
    idx=np.where(np.abs(x)>thresh)[0]
    if len(idx)==0: return None
    s=idx[0]
    seg=x[s+off:s+off+nsamp]
    if len(seg)<nsamp: seg=x[s+off:]
    z=np.where(np.diff(np.sign(seg))!=0)[0]
    return (len(z)/2)/(len(seg)/sr)
