import sys; sys.path.insert(0,'/workspace/src')
import build
CHORDS={2:['Dm','Bb','F','C'],3:['Dm','Bb','Gm','A7'],4:['F','C','Dm','Bb'],5:['Gm','A7','Dm','Dm'],8:['Dm','Dm','Bb','A7']}
MELS={2:build.MEL_A,3:build.MEL_A2,8:build.MEL_TURN,4:build.MEL_B[0:4],5:build.MEL_B[4:7]+[build.MEL_B_RUN]}
def diss(n, chord):
    tones=set(build.CHN[chord]['arp'])|set(t+12 for t in build.CHN[chord]['arp'])
    for t in tones:
        d=abs(n-t)%12; d=min(d,12-d)
        if d==1 or d==6: return d
    return None
bad=0
for p,mel in MELS.items():
    for bi,bar in enumerate(mel):
        for (r,name,dur) in bar:
            n=build.nm(name); d=diss(n,CHORDS[p][bi])
            if d is not None and dur>=3:
                print('  P%d bar%d row%-3d %-4s dur%d over %-3s -> %d'%(p,bi,r,name,dur,CHORDS[p][bi],d)); bad+=1
print('sustained clashes:',bad)
""}

{"command": "cd /workspace && python3 -c "
import sys; sys.path.insert(0,'/workspace/src')
from verify import *
import build, numpy as np
x,sr=load('/workspace/t/full32.wav')
POS={0:(build.MEL_A,2),3:(build.MEL_A2,3),4:(build.MEL_B[0:4],4),5:(build.MEL_B[4:7]+[build.MEL_B_RUN],5),8:(build.MEL_TURN,8)}
ok=bad=0
for pos,(mel,pn) in POS.items():
    t0=pos*6.4
    for bi,bar in enumerate(mel):
        for (r,name,dur) in bar:
            n=build.nm(name); f0=hz(n); t=t0+bi*1.6+r*0.1
            res=peak_near(x,sr,f0,0.30,t,0.07)
            if res is None: bad+=1; print('MISS pos%d bar%d row%d %s'%(pos,bi,r,name)); continue
            c=1200*np.log2(res[0]/f0)
            if abs(c)<60: ok+=1
            else: bad+=1; print('off pos%d bar%d row%d %s %+dc'%(pos,bi,r,name,round(c)))
print('lead notes verified: %d ok, %d bad'%(ok,bad))
""}

